import { Component, ElementRef, QueryList, ViewChildren } from '@angular/core';

type Coordinate = { row: number; col: number };
type NavigationKey = 'ArrowLeft' | 'ArrowRight' | 'ArrowUp' | 'ArrowDown' | 'Home' | 'End';

const NAVIGATION_KEYS: NavigationKey[] = [
  'ArrowLeft',
  'ArrowRight',
  'ArrowUp',
  'ArrowDown',
  'Home',
  'End'
];

@Component({
  selector: 'app-root',
  standalone: true,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  @ViewChildren('cellButton') cellButtons!: QueryList<ElementRef<HTMLButtonElement>>;

  readonly minSize = 2;
  readonly maxSize = 20;

  size = 8;
  selected: Coordinate | null = null;
  focusIndex = 0;

  get rows(): number[] {
    return Array.from({ length: this.size }, (_, index) => index);
  }

  get selectionStatus(): string {
    if (!this.selected) return 'Selected: none';
    return 'Selected: row ' + (this.selected.row + 1) + ', column ' + (this.selected.col + 1);
  }

  get queenMoves(): number {
    if (!this.selected) return 0;
    let count = 0;
    for (let row = 0; row < this.size; row += 1) {
      for (let col = 0; col < this.size; col += 1) {
        if (this.isQueenReachable(row, col)) count += 1;
      }
    }
    return count;
  }

  onSizeInput(raw: string): void {
    const parsed = Number(raw);
    const nextSize = Number.isFinite(parsed)
      ? Math.min(this.maxSize, Math.max(this.minSize, Math.trunc(parsed)))
      : this.minSize;
    this.size = nextSize;
    this.selected = null;
    this.focusIndex = 0;
  }

  onCellClick(row: number, col: number): void {
    this.selected = { row, col };
  }

  cellId(row: number, col: number): string {
    return 'chessboard-cell-' + row + '-' + col;
  }

  cellKey(row: number, col: number): string {
    return String(row) + '-' + String(col);
  }

  cellIndex(row: number, col: number): number {
    return row * this.size + col;
  }

  isSelected(row: number, col: number): boolean {
    return this.selected?.row === row && this.selected.col === col;
  }

  isQueenReachable(row: number, col: number): boolean {
    if (!this.selected || this.isSelected(row, col)) return false;
    const rowDistance = Math.abs(row - this.selected.row);
    const colDistance = Math.abs(col - this.selected.col);
    return rowDistance === 0 || colDistance === 0 || rowDistance === colDistance;
  }

  cellClass(row: number, col: number): string {
    const classes = [
      'cell',
      (row + col) % 2 === 1 ? 'cell--dark' : 'cell--light'
    ];
    if (this.isSelected(row, col)) classes.push('cell--active');
    if (this.isQueenReachable(row, col)) classes.push('cell--reachable');
    return classes.join(' ');
  }

  cellLabel(row: number, col: number): string {
    const base = 'Row ' + (row + 1) + ', column ' + (col + 1);
    if (this.isSelected(row, col)) return base + ', selected';
    if (this.isQueenReachable(row, col)) return base + ', reachable by queen';
    return base;
  }

  setFocusIndex(index: number): void {
    this.focusIndex = index;
  }

  focusCell(index: number): void {
    this.focusIndex = index;
    this.cellButtons.get(index)?.nativeElement.focus();
  }

  onCellKeydown(event: KeyboardEvent, index: number): void {
    const key = event.key as NavigationKey;
    if (!NAVIGATION_KEYS.includes(key)) return;

    event.preventDefault();
    const row = Math.floor(index / this.size);
    const col = index % this.size;
    let nextIndex = index;

    if (key === 'ArrowLeft') nextIndex = row * this.size + (col + this.size - 1) % this.size;
    else if (key === 'ArrowRight') nextIndex = row * this.size + (col + 1) % this.size;
    else if (key === 'ArrowUp') nextIndex = ((row + this.size - 1) % this.size) * this.size + col;
    else if (key === 'ArrowDown') nextIndex = ((row + 1) % this.size) * this.size + col;
    else if (key === 'Home') nextIndex = row * this.size;
    else if (key === 'End') nextIndex = row * this.size + this.size - 1;

    this.focusCell(nextIndex);
  }
}

