:host {
  display: block;
  min-width: 0;
  min-height: 100%;
}

* {
  box-sizing: border-box;
}

.page {
  width: 100%;
  min-height: 100vh;
  padding: 24px;
  display: grid;
  place-items: center;
  background: #0a0a0a;
  color: #e5e7eb;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.card {
  width: 100%;
  max-width: 760px;
  min-width: 0;
  padding: 18px;
  display: grid;
  gap: 14px;
  border: 1px solid #1f2937;
  border-radius: 14px;
  background: #0b1020;
}

.title {
  margin: 0;
  font-size: 20px;
  font-weight: 800;
}

.subtitle {
  margin: 0;
  color: #9ca3af;
  font-size: 13px;
}

.size {
  width: max-content;
  display: inline-grid;
  gap: 6px;
  color: #9ca3af;
  font-size: 12px;
}

.size input {
  width: 90px;
  padding: 8px 10px;
  border: 1px solid #374151;
  border-radius: 10px;
  background: #0a0f1e;
  color: #e5e7eb;
}

.status {
  margin: 0;
  padding: 8px 10px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  border: 1px solid #1f2937;
  border-radius: 10px;
  background: #0a0f1e;
  font-size: 13px;
}

.reachability-status {
  color: #bfdbfe;
}

.board {
  width: 100%;
  max-width: 560px;
  min-width: 0;
  display: grid;
  overflow: hidden;
  border: 1px solid #374151;
  border-radius: 12px;
}

.cell {
  width: 100%;
  min-width: 0;
  padding: 0;
  aspect-ratio: 1 / 1;
  border: none;
  outline: none;
  cursor: pointer;
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.15);
  transition: box-shadow 120ms ease;
}

.cell--light {
  background: #e5e7eb;
}

.cell--dark {
  background: #334155;
}

.cell:hover {
  box-shadow: inset 0 0 0 2px rgba(14, 165, 233, 0.65);
}

.cell--reachable {
  box-shadow: inset 0 0 0 3px #38bdf8;
}

.cell--active {
  box-shadow: inset 0 0 0 3px #facc15;
}

.cell:focus-visible {
  position: relative;
  z-index: 1;
  box-shadow: inset 0 0 0 3px #a3e635;
}

@media (max-width: 520px) {
  .page {
    padding: 12px;
  }

  .card {
    padding: 14px;
  }
}

